def _validate_choose_harbinger(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    ctx = dict(getattr(request, "context", {}) or {})
    ability_key = str(ctx.get("ability", "") or "").strip().lower()
    if ability_key == "helhunt_aspect_of_the_beast" and is_skip_choice(request, result):
        return ("Aspect of the Beast selection cannot be skipped.",)
    if is_skip_choice(request, result):
        return ()
    payload = _option_payload(request, result)
    army = _resolve_army(game, request, payload)
    if army is None or getattr(army, "harbingers_of_dread", None) is None:
        return ("Harbingers manager not found.",)
    if ability_key == "helhunt_aspect_of_the_beast":
        ck_mgr = getattr(army, "chaos_knights_detachments", None)
        if ck_mgr is None or not bool(getattr(ck_mgr, "is_helhunt_lance", lambda: False)()):
            return ("Aspect of the Beast requires Helhunt Lance detachment.",)
        source_unit = resolve_unit(
            game,
            payload.get("source_unit_id") or ctx.get("source_unit_id") or payload.get("unit_id") or ctx.get("unit_id"),
        )
        if source_unit is None:
            return ("Aspect of the Beast source unit was not found.",)
        choice_key = str(payload.get("choice_key") or payload.get("key") or "").strip().upper()
        if not choice_key:
            return ("Aspect of the Beast selection requires choice_key.",)
        allowed = {
            str(item or "").strip().upper()
            for item in list(ctx.get("allowed_choice_keys", []) or [])
            if str(item or "").strip()
        }
        if allowed and choice_key not in allowed:
            return ("Selected Dread ability is not eligible for Aspect of the Beast.",)
        player = _resolve_player(game, request, payload)
        if player is None:
            player = getattr(army, "player", None)
        validate_choice = getattr(ck_mgr, "helhunt_aspect_choice_is_valid", None)
        if not callable(validate_choice):
            return ("Aspect of the Beast validation is unavailable.",)
        valid, reason = validate_choice(
            source_unit,
            choice_key,
            game=game,
            player=player,
        )
        if not bool(valid):
            return (str(reason or "Aspect of the Beast selection is invalid."),)
        return ()
    if ability_key == "traitoris_paragons_of_terror_bonus":
        ck_mgr = getattr(army, "chaos_knights_detachments", None)
        if ck_mgr is None:
            return ("Chaos Knights detachment manager not found.",)
        battle_round = ctx.get("battle_round")
        can_queue = getattr(ck_mgr, "can_queue_traitoris_paragons_bonus_choice", None)
        if callable(can_queue):
            try:
                if not bool(can_queue(battle_round=int(battle_round or 0), game=game)):
                    return ("Paragons of Terror bonus choice is not available.",)
            except (TypeError, ValueError):
                return ("Paragons of Terror battle_round is invalid.",)
        choice_key = str(payload.get("choice_key") or payload.get("key") or "").strip().upper()
        allowed = {
            str(item or "").strip().upper()
            for item in list(ctx.get("allowed_choice_keys", []) or [])
            if str(item or "").strip()
        }
        if allowed and choice_key not in allowed:
            return ("Selected Dread ability is not eligible for Paragons of Terror.",)
    return ()


def _apply_choose_harbinger(game: object, request: DecisionRequest, result: DecisionResult):
    payload = _option_payload(request, result)
    army = _resolve_army(game, request, payload)
    if army is None:
        raise RuntimeError("Harbingers army not found.")
    mgr = getattr(army, "harbingers_of_dread", None)
    if mgr is None:
        raise RuntimeError("Harbingers manager not found.")
    context = dict(getattr(request, "context", {}) or {})
    ability_key = str(context.get("ability", "") or "").strip().lower()
    battle_round = context.get("battle_round")
    ck_mgr = getattr(army, "chaos_knights_detachments", None)
    if ability_key == "helhunt_aspect_of_the_beast":
        source_unit = resolve_unit(
            game,
            payload.get("source_unit_id") or context.get("source_unit_id") or payload.get("unit_id") or context.get("unit_id"),
        )
        if source_unit is None:
            raise RuntimeError("Aspect of the Beast source unit was not found.")
        choice_key = str(payload.get("choice_key") or payload.get("key") or "").strip().upper()
        if not choice_key:
            raise RuntimeError("Aspect of the Beast selection requires choice_key.")
        player = _resolve_player(game, request, payload)
        if player is None:
            player = getattr(army, "player", None)
        apply_choice = getattr(ck_mgr, "apply_helhunt_aspect_choice", None) if ck_mgr is not None else None
        if not callable(apply_choice):
            raise RuntimeError("Aspect of the Beast apply handler is unavailable.")
        outcome = apply_choice(source_unit, choice_key, game=game, player=player)
        if not bool(outcome.get("ok", False)):
            raise RuntimeError(str(outcome.get("reason", "") or "Aspect of the Beast selection failed."))
        choice_name = str(outcome.get("choice_name", choice_key) or choice_key)
        _log_action_for_players(game, player, f"Aspect of the Beast: {choice_name}.")
        return outcome
    if is_skip_choice(request, result):
        if ability_key == "traitoris_paragons_of_terror_bonus":
            mark_used = getattr(ck_mgr, "mark_traitoris_paragons_bonus_used", None) if ck_mgr is not None else None
            if callable(mark_used):
                mark_used(battle_round=battle_round, game=game)
            try:
                player = getattr(army, "player", None)
                _log_action_for_players(game, player, "Paragons of Terror: no additional Dread ability selected.")
            except Exception:
                pass
        return None
    choice = payload.get("choice_key") or payload.get("key")
    applied = None
    if bool(payload.get("random", False)) or str(choice or "").strip().upper() == "ROLL":
        rolls_raw = payload.get("rolls")
        selected_keys = payload.get("selected_keys")
        rolls = []
        for value in list(rolls_raw or []):
            try:
                rolls.append(int(value or 0))
            except (TypeError, ValueError):
                continue
        queue_malevolent = getattr(ck_mgr, "queue_traitoris_malevolent_heraldry_reroll_choice", None) if ck_mgr is not None else None
        if (
            ability_key != "traitoris_paragons_of_terror_bonus"
            and callable(queue_malevolent)
            and rolls
        ):
            queued = queue_malevolent(
                initial_rolls=list(rolls),
                battle_round=int(battle_round or 0),
                game=game,
                player=getattr(army, "player", None),
            )
            if queued is not None:
                try:
                    player = getattr(army, "player", None)
                    roll_text = ", ".join(str(int(r)) for r in list(rolls))
                    _log_action_for_players(game, player, f"Harbingers of Dread: rolled {roll_text} (Malevolent Heraldry selection pending).")
                except Exception:
                    pass
                return {"pending_malevolent_heraldry_reroll": True, "rolls": list(rolls)}
        if rolls or selected_keys:
            applied = mgr.apply_roll_results(rolls=rolls, selected_keys=selected_keys, battle_round=battle_round)
        else:
            applied = mgr.roll_dread_abilities(battle_round=battle_round)
    else:
        applied = bool(mgr.select_dread_ability(choice, battle_round=battle_round))
    try:
        player = getattr(army, "player", None)
        if isinstance(applied, dict):
            selected = [getattr(d, "name", None) or getattr(d, "key", None) for d in list(applied.get("selected", []) or [])]
            selected = [str(s) for s in selected if s]
            rolls_list = list(applied.get("rolls", []) or [])
            if selected:
                label = ", ".join(selected)
            else:
                label = _option_label(request, result) or "Roll"
            roll_text = ", ".join(str(int(r)) for r in rolls_list) if rolls_list else "?"
            _log_action_for_players(game, player, f"Harbingers of Dread: {label} (dice: {roll_text})")
        else:
            label = _option_label(request, result) or str(choice)
            if label:
                _log_action_for_players(game, player, f"Harbingers of Dread: {label} (Battle Round {battle_round})")
    except Exception:
        pass
    if ability_key == "traitoris_paragons_of_terror_bonus":
        mark_used = getattr(ck_mgr, "mark_traitoris_paragons_bonus_used", None) if ck_mgr is not None else None
        if callable(mark_used):
            mark_used(battle_round=battle_round, game=game)
        return applied
    queue_bonus = getattr(ck_mgr, "queue_traitoris_paragons_bonus_choice", None) if ck_mgr is not None else None
    if callable(queue_bonus):
        queue_bonus(
            battle_round=battle_round,
            game=game,
            player=getattr(army, "player", None),
        )
    return applied


def _validate_choose_martial_katah(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    if is_skip_choice(request, result):
        return ()
    payload = _option_payload(request, result)
    unit_val = payload.get("unit_id") or payload.get("unit")
    choice = payload.get("choice_key") or payload.get("key")
    if unit_val is None or choice is None:
        return ("Martial Ka'tah requires unit_id and choice.",)
    unit = resolve_unit(game, unit_val)
    if unit is None:
        return ("Martial Ka'tah unit not found.",)
    choice_norm = str(choice or "").strip().upper()
    selection_kind = str(request.context.get("selection_kind", "") or payload.get("selection_kind", "") or "")
    if choice_norm == "BOTH":
        if selection_kind == "exquisite_swordsmanship":
            return ("Master of the Stances cannot be used for Exquisite Swordsmanship.",)
        spec = getattr(unit, "master_of_stances_spec", lambda: None)()
        if not spec:
            return ("Master of the Stances not available.",)
        ability_key = str(payload.get("ability_key") or spec.get("ability_key") or "master_of_stances").strip().lower()
        model_id = str(payload.get("model_id") or spec.get("model_id") or "")
        if model_id:
            model = resolve_model(game, model_id)
            if model is None:
                return ("Master of the Stances model not found.",)
            if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
                return ("Master of the Stances already used.",)
    return ()


def _apply_choose_martial_katah(game: object, request: DecisionRequest, result: DecisionResult):
    if is_skip_choice(request, result):
        return None
    payload = _option_payload(request, result)
    unit = resolve_unit(game, payload.get("unit_id") or payload.get("unit"))
    if unit is None:
        raise RuntimeError("Martial Ka'tah unit not found.")
    choice = payload.get("choice_key") or payload.get("key")
    choice_norm = str(choice or "").strip().upper()
    selection_kind = str(request.context.get("selection_kind", "") or payload.get("selection_kind", "") or "")
    if selection_kind == "exquisite_swordsmanship":
        unit.set_exquisite_swordsmanship_choice(str(choice))
    else:
        if choice_norm == "BOTH":
            spec = getattr(unit, "master_of_stances_spec", lambda: None)()
            ability_name = ""
            if isinstance(spec, dict):
                ability_name = str(spec.get("source") or "Master of the Stances").strip()
            ability_key = str(payload.get("ability_key") or (spec.get("ability_key") if isinstance(spec, dict) else "") or "master_of_stances").strip().lower()
            model_id = str(payload.get("model_id") or (spec.get("model_id") if isinstance(spec, dict) else "") or "")
            if model_id:
                model = resolve_model(game, model_id)
                if model is not None:
                    getattr(model, "mark_used_once_per_battle", lambda _k, **_kw: None)(
                        ability_key,
                        ability_name=ability_name or "Master of the Stances",
                        source="datasheet",
                    )
        unit.set_martial_katah_choice(str(choice))
    return str(choice)


def _validate_choose_moment_shackle(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    if is_skip_choice(request, result):
        return ()
    payload = _option_payload(request, result)
    unit_val = payload.get("unit_id") or request.context.get("unit_id")
    model_val = payload.get("model_id") or request.context.get("model_id")
    choice = payload.get("choice") or payload.get("choice_key") or payload.get("key")
    if not unit_val or not model_val or not choice:
        return ("Moment Shackle requires unit_id, model_id, and choice.",)
    unit = resolve_unit(game, unit_val)
    if unit is None:
        return ("Moment Shackle unit not found.",)
    model = resolve_model(game, model_val)
    if model is None:
        return ("Moment Shackle model not found.",)
    spec = getattr(unit, "model_moment_shackle_spec", lambda _m: None)(model)
    if not spec:
        return ("Moment Shackle not available.",)
    ability_key = str(payload.get("ability_key") or spec.get("ability_key") or "moment_shackle").strip().lower()
    if getattr(model, "has_used_once_per_battle", lambda _k: False)(ability_key):
        return ("Moment Shackle already used.",)
    choice_norm = str(choice or "").strip().lower()
    if choice_norm not in ("attacks", "attack", "invuln", "invulnerable", "invulnerable_save"):
        return ("Moment Shackle choice must be attacks or invulnerable save.",)
    return ()


def _apply_choose_moment_shackle(game: object, request: DecisionRequest, result: DecisionResult):
    if is_skip_choice(request, result):
        return None
    payload = _option_payload(request, result)
    unit = resolve_unit(game, payload.get("unit_id") or request.context.get("unit_id"))
    model = resolve_model(game, payload.get("model_id") or request.context.get("model_id"))
    if unit is None or model is None:
        raise RuntimeError("Moment Shackle unit/model not found.")
    spec = getattr(unit, "model_moment_shackle_spec", lambda _m: None)(model)
    if not spec:
        raise RuntimeError("Moment Shackle not available.")
    ability_name = str(spec.get("source") or "Moment Shackle").strip() or "Moment Shackle"
    ability_key = str(payload.get("ability_key") or spec.get("ability_key") or "moment_shackle").strip().lower()
    choice = payload.get("choice") or payload.get("choice_key") or payload.get("key")
    choice_norm = str(choice or "").strip().lower()
    if choice_norm in ("attacks", "attack"):
        weapon_name = str(payload.get("weapon_name") or spec.get("weapon_name") or "Watcher's Axe").strip()
        try:
            attacks = int(payload.get("attacks", spec.get("attacks", 0)) or 0)
        except Exception:
            attacks = int(spec.get("attacks", 0) or 0)
        getattr(model, "set_temporary_weapon_attacks_override", lambda **_kw: None)(
            key=f"{ability_key}:attacks",
            weapon_name=weapon_name,
            attacks_value=int(attacks or 0),
            source=ability_name,
            expires_phase="FIGHT_PHASE",
        )
    elif choice_norm in ("invuln", "invulnerable", "invulnerable_save"):
        try:
            invuln = int(payload.get("invuln", spec.get("invuln", 0)) or 0)
        except Exception:
            invuln = int(spec.get("invuln", 0) or 0)
        getattr(model, "set_temporary_invulnerable_save", lambda **_kw: None)(
            key=f"{ability_key}:invuln",
            value=int(invuln or 0),
            source=ability_name,
            expires_phase="FIGHT_PHASE",
        )
    getattr(model, "mark_used_once_per_battle", lambda _k, **_kw: None)(
        ability_key,
        ability_name=ability_name,
        source="datasheet",
    )
    try:
        player = getattr(getattr(unit, "get_parent_army", lambda: None)(), "player", None)
    except Exception:
        player = None
    try:
        choice_label = _option_label(request, result) or str(choice)
        mname = str(getattr(model, "name", "Model") or "Model")
        if choice_label:
            _log_action_for_players(game, player, f"{ability_name}: {mname} selected {choice_label}.")
    except Exception:
        pass
    return str(choice)


def _validate_use_miracle_die(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    if is_skip_choice(request, result):
        return ()
    return validate_option_choice(request, result)


def _apply_use_miracle_die(game: object, request: DecisionRequest, result: DecisionResult):
    if is_skip_choice(request, result):
        return None
    payload = _option_payload(request, result)
    value = payload.get("die_value", payload.get("value"))
    if value is None:
        return None
    return int(value)


def _validate_choose_plague(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    payload = _option_payload(request, result)
    army = _resolve_army(game, request, payload)
    if army is None or getattr(army, "nurgles_gift", None) is None:
        return ("Nurgle's Gift manager not found.",)
    ctx = dict(getattr(request, "context", {}) or {})
    ability = str(ctx.get("ability", "") or "").strip().lower()
    if ability == "manifold_maladies":
        dg_mgr = getattr(army, "death_guard_detachments", None)
        can_select = getattr(dg_mgr, "can_select_manifold_maladies", None) if dg_mgr is not None else None
        battle_round = payload.get("battle_round")
        if battle_round is None:
            battle_round = ctx.get("battle_round")
        if not callable(can_select) or not bool(can_select(game=game, battle_round=battle_round)):
            return ("Manifold Maladies cannot be selected right now.",)
        if is_skip_choice(request, result):
            return ()
        choice = payload.get("choice_key") or payload.get("key")
        if choice is None:
            return ("Plague choice requires key.",)
        choice_key = str(choice or "").strip().upper()
        allowed_keys = {
            str(v or "").strip().upper()
            for v in list(ctx.get("allowed_choice_keys", []) or [])
            if str(v or "").strip()
        }
        if allowed_keys and choice_key not in allowed_keys:
            return ("Selected Plague is not in this request's candidate list.",)
        try:
            from ...rules.nurgles_gift import DEFAULT_PLAGUES
        except Exception:
            DEFAULT_PLAGUES = ()
        valid_keys = {str(getattr(plague, "key", "") or "").strip().upper() for plague in list(DEFAULT_PLAGUES)}
        if choice_key not in valid_keys:
            return ("Invalid Plague choice.",)
        return ()
    if ability in ("final_ingredient", "cornucophagus"):
        dg_mgr = getattr(army, "death_guard_detachments", None)
        if dg_mgr is None:
            return ("Death Guard detachment manager not found.",)
        source_unit = resolve_unit(game, payload.get("source_unit_id") or ctx.get("source_unit_id"))
        if source_unit is None:
            return ("Plague choice requires a valid source unit.",)
        if ability == "final_ingredient":
            can_select = getattr(dg_mgr, "can_select_final_ingredient", None)
            if not callable(can_select) or not bool(can_select(source_unit, game=game)):
                return ("Final Ingredient cannot be selected right now.",)
        if ability == "cornucophagus":
            can_select = getattr(dg_mgr, "can_select_cornucophagus", None)
            if not callable(can_select) or not bool(can_select(source_unit, game=game)):
                return ("Cornucophagus cannot be selected right now.",)
        if is_skip_choice(request, result):
            return ()
        choice = payload.get("choice_key") or payload.get("key")
        if choice is None:
            return ("Plague choice requires key.",)
        choice_key = str(choice or "").strip().upper()
        allowed_keys = {
            str(v or "").strip().upper()
            for v in list(ctx.get("allowed_choice_keys", []) or [])
            if str(v or "").strip()
        }
        if allowed_keys and choice_key not in allowed_keys:
            return ("Selected Plague is not in this request's candidate list.",)
        try:
            from ...rules.nurgles_gift import DEFAULT_PLAGUES
        except Exception:
            DEFAULT_PLAGUES = ()
        valid_keys = {str(getattr(plague, "key", "") or "").strip().upper() for plague in list(DEFAULT_PLAGUES)}
        if choice_key not in valid_keys:
            return ("Invalid Plague choice.",)
        return ()
    if is_skip_choice(request, result):
        return ()
    choice = payload.get("choice_key") or payload.get("key")
    if choice is None:
        return ("Plague choice requires key.",)
    return ()


def _apply_choose_plague(game: object, request: DecisionRequest, result: DecisionResult):
    payload = _option_payload(request, result)
    army = _resolve_army(game, request, payload)
    if army is None:
        raise RuntimeError("Nurgle's Gift army not found.")
    ctx = dict(getattr(request, "context", {}) or {})
    ability = str(ctx.get("ability", "") or "").strip().lower()
    if ability == "manifold_maladies":
        dg_mgr = getattr(army, "death_guard_detachments", None)
        if dg_mgr is None:
            raise RuntimeError("Death Guard detachment manager not found.")
        select_fn = getattr(dg_mgr, "select_manifold_maladies", None)
        if not callable(select_fn):
            raise RuntimeError("Manifold Maladies selector is unavailable.")
        battle_round = payload.get("battle_round")
        if battle_round is None:
            battle_round = ctx.get("battle_round")
        player = _resolve_player(game, request, payload)
        if player is None:
            player = getattr(army, "player", None)
        ability_name = str(ctx.get("ability_name", "") or "Manifold Maladies").strip() or "Manifold Maladies"
        if is_skip_choice(request, result):
            applied = bool(select_fn("", battle_round=battle_round))
            if applied:
                _log_action_for_players(
                    game,
                    player,
                    f"{ability_name}: none selected (Battle Round {battle_round}).",
                )
            return None
        choice = payload.get("choice_key") or payload.get("key")
        applied = bool(select_fn(choice, battle_round=battle_round))
        if not applied:
            raise RuntimeError("Manifold Maladies selection failed.")
        label = _option_label(request, result) or str(choice)
        _log_action_for_players(
            game,
            player,
            f"{ability_name}: {label} (Battle Round {battle_round}).",
        )
        return str(choice)
    if ability in ("final_ingredient", "cornucophagus"):
        dg_mgr = getattr(army, "death_guard_detachments", None)
        if dg_mgr is None:
            raise RuntimeError("Death Guard detachment manager not found.")
        source_unit = resolve_unit(game, payload.get("source_unit_id") or ctx.get("source_unit_id"))
        if source_unit is None:
            raise RuntimeError("Plague choice source unit not found.")
        choice = payload.get("choice_key") or payload.get("key")
        if ability == "final_ingredient":
            select_fn = getattr(dg_mgr, "select_final_ingredient", None)
            if not callable(select_fn):
                raise RuntimeError("Final Ingredient selector is unavailable.")
            applied = bool(select_fn(source_unit, choice, game=game))
            if not applied:
                raise RuntimeError("Final Ingredient selection failed.")
        else:
            select_fn = getattr(dg_mgr, "select_cornucophagus", None)
            if not callable(select_fn):
                raise RuntimeError("Cornucophagus selector is unavailable.")
            applied = bool(select_fn(source_unit, choice))
            if not applied:
                raise RuntimeError("Cornucophagus selection failed.")
        player = _resolve_player(game, request, payload)
        if player is None:
            player = getattr(army, "player", None)
        ability_name = str(
            ctx.get("ability_name", "")
            or ("Final Ingredient" if ability == "final_ingredient" else "Cornucophagus")
        ).strip() or ("Final Ingredient" if ability == "final_ingredient" else "Cornucophagus")
        label = _option_label(request, result) or str(choice)
        _log_action_for_players(game, player, f"{ability_name}: {label}.")
        return str(choice)
    if is_skip_choice(request, result):
        return None
    mgr = getattr(army, "nurgles_gift", None)
    if mgr is None:
        raise RuntimeError("Nurgle's Gift manager not found.")
    choice = payload.get("choice_key") or payload.get("key")
    mgr.active_plague_key = str(choice)
    return str(choice)


def _validate_choose_start_of_battle_keyword(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    payload = _option_payload(request, result)
    keyword = payload.get("keyword") or _option_label(request, result)
    if not keyword:
        return ("Start-of-battle keyword selection requires keyword.",)
    model = resolve_model(game, payload.get("model_id") or request.context.get("model_id"))
    if model is None:
        return ("Start-of-battle keyword selection model not found.",)
    unit = getattr(model, "parent_unit", None)
    if unit is None:
        unit = resolve_unit(game, payload.get("unit_id") or request.context.get("unit_id"))
    if unit is None:
        return ("Start-of-battle keyword selection unit not found.",)
    ability_key = payload.get("ability_key") or request.context.get("ability_key")
    spec_fn = getattr(unit, "model_start_of_battle_keyword_selection_specs", None)
    if callable(spec_fn):
        specs = spec_fn(model) or []
    elif hasattr(unit, "model_start_of_battle_keyword_reroll_ones_specs"):
        specs = unit.model_start_of_battle_keyword_reroll_ones_specs(model) or []
    else:
        specs = []
    if not specs:
        return ("Start-of-battle keyword selection ability not found.",)
    if ability_key:
        for spec in list(specs or []):
            if str(spec.get("ability_key", "") or "").strip().lower() == str(ability_key).strip().lower():
                if str(keyword).strip().upper() not in {str(k).strip().upper() for k in (spec.get("keywords", []) or [])}:
                    return ("Selected keyword is not valid for this ability.",)
                return ()
        return ("Start-of-battle keyword selection ability key not found.",)
    return ()


def _apply_choose_start_of_battle_keyword(game: object, request: DecisionRequest, result: DecisionResult):
    payload = _option_payload(request, result)
    keyword = payload.get("keyword") or _option_label(request, result)
    if not keyword:
        raise RuntimeError("Start-of-battle keyword selection requires keyword.")
    model = resolve_model(game, payload.get("model_id") or request.context.get("model_id"))
    if model is None:
        raise RuntimeError("Start-of-battle keyword selection model not found.")
    unit = getattr(model, "parent_unit", None)
    if unit is None:
        unit = resolve_unit(game, payload.get("unit_id") or request.context.get("unit_id"))
    if unit is None:
        raise RuntimeError("Start-of-battle keyword selection unit not found.")
    source = payload.get("ability_name") or request.context.get("ability_name") or "Start of battle keyword selection"
    ability_key = payload.get("ability_key") or request.context.get("ability_key")
    spec_fn = getattr(unit, "model_start_of_battle_keyword_selection_specs", None)
    if callable(spec_fn):
        specs = spec_fn(model) or []
    elif hasattr(unit, "model_start_of_battle_keyword_reroll_ones_specs"):
        specs = unit.model_start_of_battle_keyword_reroll_ones_specs(model) or []
    else:
        specs = []
    matched_spec = None
    ability_key_value = str(ability_key or "").strip().lower()
    if ability_key_value:
        for spec in list(specs or []):
            spec_key = str(spec.get("ability_key", "") or "").strip().lower()
            if spec_key == ability_key_value:
                matched_spec = spec
                break
    elif len(specs) == 1:
        matched_spec = specs[0]
    applied = False
    try:
        applied = bool(
            unit.apply_start_of_battle_keyword_reroll_choice(
                model,
                keyword=str(keyword),
                source=str(source),
                ability_key=str(ability_key or ""),
                selection_kind=str((matched_spec or {}).get("selection_kind", "reroll_ones") or "reroll_ones"),
                reroll_hit_ones=bool((matched_spec or {}).get("reroll_hit_ones", True)),
                reroll_wound_ones=bool((matched_spec or {}).get("reroll_wound_ones", True)),
            )
        )
    except Exception:
        applied = False
    try:
        player = getattr(getattr(unit, "get_parent_army", lambda: None)(), "player", None)
    except Exception:
        player = None
    try:
        mname = str(getattr(model, "name", "Model") or "Model")
        if applied:
            _log_action_for_players(game, player, f"{mname} selected {str(keyword).upper()} for {source}.")
    except Exception:
        pass
    return str(keyword)


def _resolve_emperors_children_manager(army: object):
    if army is None:
        return None
    mgr = getattr(army, "emperors_children", None)
    if mgr is not None:
        return mgr
    return getattr(army, "emperors_children_detachments", None)


def _validate_choose_pledge(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    if is_skip_choice(request, result):
        return ()
    payload = _option_payload(request, result)
    value = payload.get("pledge_value", payload.get("value"))
    if value is None:
        return ("Pledge selection requires value.",)
    army = _resolve_army(game, request, payload)
    mgr = _resolve_emperors_children_manager(army)
    if mgr is None:
        return ("Emperor's Children manager not found.",)
    if not getattr(mgr, "is_coterie_of_conceited", lambda: False)():
        return ("Pledges to the Dark Prince requires Coterie of the Conceited.",)
    if not getattr(mgr, "warlord_on_battlefield", lambda: False)():
        return ("Pledges to the Dark Prince requires your warlord on the battlefield.",)
    return ()


def _apply_choose_pledge(game: object, request: DecisionRequest, result: DecisionResult):
    if is_skip_choice(request, result):
        return None
    payload = _option_payload(request, result)
    army = _resolve_army(game, request, payload)
    if army is None:
        raise RuntimeError("Emperor's Children army not found.")
    mgr = _resolve_emperors_children_manager(army)
    if mgr is None:
        raise RuntimeError("Emperor's Children manager not found.")
    value = payload.get("pledge_value", payload.get("value"))
    battle_round = request.context.get("battle_round")
    max_value = request.context.get("max_value")
    return int(mgr.set_pledge_target(int(value), battle_round=battle_round, max_value=max_value))


def _resurrection_orb_unit_on_battlefield(unit) -> bool:
    if unit is None:
        return False
    is_alive_fn = getattr(unit, "is_alive", None)
    if callable(is_alive_fn):
        if not bool(is_alive_fn()):
            return False
    elif getattr(unit, "is_alive", True) is False:
        return False
    if not bool(getattr(unit, "deployed", True)):
        return False
    if str(getattr(unit, "reserve_status", "deployed") or "deployed") != "deployed":
        return False
    in_reserves_fn = getattr(unit, "is_in_reserves", None)
    if callable(in_reserves_fn) and bool(in_reserves_fn()):
        return False
    if bool(getattr(unit, "embarked_in", None)) or bool(getattr(unit, "is_embarked", False)):
        return False
    return True


def _resurrection_orb_army_used_this_turn(army, *, turn: int, turn_owner_id: str) -> bool:
    if army is None:
        return False
    for unit in list(getattr(army, "units", []) or []):
        if unit is None:
            continue
        sr = getattr(unit, "special_rules", None)
        if not isinstance(sr, dict):
            continue
        try:
            used_turn = int(sr.get("resurrection_orb_used_turn", -1))
        except (TypeError, ValueError):
            continue
        if used_turn != int(turn):
            continue
        used_owner = str(sr.get("resurrection_orb_used_turn_owner", "") or "")
        if turn_owner_id and used_owner and used_owner != turn_owner_id:
            continue
        return True
    return False


def _mark_resurrection_orb_used_this_turn(source_unit, *, turn: int, turn_owner_id: str) -> None:
    if source_unit is None:
        return
    sr = getattr(source_unit, "special_rules", None)
    if not isinstance(sr, dict):
        sr = {}
    updated = dict(sr)
    updated["resurrection_orb_used_turn"] = int(turn)
    updated["resurrection_orb_used_turn_owner"] = str(turn_owner_id or "")
    source_unit.special_rules = updated


def _model_within_objective_marker_range(model: object, objective: object, *, range_value: float) -> bool:
    if model is None or objective is None:
        return False
    try:
        rng = float(range_value or 0.0)
    except (TypeError, ValueError):
        rng = 0.0
    if rng <= 0.0:
        return False
    location = getattr(objective, "location", None)
    if location is None:
        return False
    if bool(getattr(location, "removed", False)):
        return False
    get_location = getattr(model, "get_location", None)
    model_location = get_location() if callable(get_location) else None
    if not model_location or len(model_location) < 3:
        return False
    try:
        mx = float(model_location[0])
        my = float(model_location[1])
        mz = float(model_location[2])
    except (TypeError, ValueError):
        return False
    if hasattr(location, "x") and hasattr(location, "y"):
        try:
            ox = float(getattr(location, "x", 0.0) or 0.0)
            oy = float(getattr(location, "y", 0.0) or 0.0)
            oz = float(getattr(location, "z", 0.0) or 0.0)
        except (TypeError, ValueError):
            return False
    elif isinstance(location, (tuple, list)) and len(location) >= 2:
        try:
            ox = float(location[0])
            oy = float(location[1])
            oz = float(location[2]) if len(location) >= 3 else 0.0
        except (TypeError, ValueError):
            return False
    else:
        return False
    base_radius_fn = getattr(getattr(model, "model_base", None), "get_radius", None)
    try:
        base_radius = float(base_radius_fn() if callable(base_radius_fn) else 0.0)
    except (TypeError, ValueError):
        base_radius = 0.0
    dx = mx - ox
    dy = my - oy
    dz = mz - oz
    return ((dx * dx) + (dy * dy) + (dz * dz)) ** 0.5 <= float(rng + base_radius) + 1e-6


def _collect_start_any_command_phase_objective_battleshock_targeted_ids(
    game: object,
    *,
    turn: int,
    turn_owner_id: str = "",
) -> set[str]:
    if game is None or int(turn or 0) <= 0:
        return set()
    targeted: set[str] = set()
    normalized_turn_owner = str(turn_owner_id or "").strip()
    for player in list(getattr(game, "players", []) or []):
        if player is None:
            continue
        army = getattr(player, "army", None)
        if army is None:
            get_army = getattr(player, "get_army", None)
            army = get_army() if callable(get_army) else None
        if army is None:
            continue
        seen_roots: set[str] = set()
        for unit in list(getattr(army, "units", []) or []):
            if unit is None:
                continue
            get_root = getattr(unit, "get_attached_unit_root", None)
            root = get_root() if callable(get_root) else unit
            if root is None:
                continue
            root_id = str(get_entity_id(root) or "")
            if root_id and root_id in seen_roots:
                continue
            if root_id:
                seen_roots.add(root_id)
            sr = getattr(root, "special_rules", None)
            if not isinstance(sr, dict):
                continue
            try:
                used_turn = int(sr.get("start_any_command_phase_objective_battleshock_turn", 0) or 0)
            except (TypeError, ValueError):
                used_turn = 0
            if int(used_turn) != int(turn):
                continue
            used_turn_owner = str(
                sr.get("start_any_command_phase_objective_battleshock_turn_owner_id", "")
                or sr.get("start_any_command_phase_objective_battleshock_turn_owner", "")
                or ""
            ).strip()
            if normalized_turn_owner and used_turn_owner and used_turn_owner != normalized_turn_owner:
                continue
            for objective_id in list(sr.get("start_any_command_phase_objective_battleshock_objective_ids", []) or []):
                key = str(objective_id or "").strip()
                if key:
                    targeted.add(key)
    return targeted


def _validate_choose_quarry(game: object, request: DecisionRequest, result: DecisionResult) -> Sequence[str]:
    errors = list(validate_option_choice(request, result))
    if errors:
        return errors
    ctx = dict(getattr(request, "context", {}) or {})
    ability = str(ctx.get("ability", "") or "")
    if ability == "tau_kauyon_tempting_trap_objective":
        payload = _option_payload(request, result)
        if is_skip_choice(request, result):
            return ("A Tempting Trap objective selection cannot be skipped.",)
        army = _resolve_army(game, request, payload)
        if army is None:
            return ("A Tempting Trap army was not found.",)
        mgr = getattr(army, "tau_empire_detachments", None)
        if mgr is None or not bool(getattr(mgr, "is_kauyon", lambda: False)()):
            return ("A Tempting Trap requires the Kauyon detachment.",)
        source_unit = resolve_unit(
            game,
            payload.get("source_unit_id")
            or ctx.get("source_unit_id")
            or payload.get("unit_id")
            or ctx.get("unit_id"),
        )
        if source_unit is None:
            return ("A Tempting Trap source unit was not found.",)
        source_root = (
            source_unit.get_attached_unit_root()
            if hasattr(source_unit, "get_attached_unit_root")
            else source_unit
        )
        if source_root is None:
            return ("A Tempting Trap source unit was not found.",)
        objective_id = str(payload.get("objective_id") or ctx.get("objective_id") or "").strip()
        if not objective_id:
            return ("A Tempting Trap selection requires objective_id.",)
        objective = get_objective(game, objective_id)
        if objective is None:
            game_map = getattr(game, "map", None)
            for candidate in list(getattr(game_map, "objectives", []) or []):
                candidate_id = str(getattr(candidate, "id", "") or get_entity_id(candidate) or "").strip()
                if candidate_id == objective_id:
                    objective = candidate
                    break
        if objective is None:
            return ("A Tempting Trap selected objective marker was not found.",)
        candidate_ids = {
            str(value or "").strip()
            for value in list(ctx.get("candidate_objective_ids", []) or [])
            if str(value or "").strip()
        }
        if candidate_ids and objective_id not in candidate_ids:
            return ("A Tempting Trap selected objective marker is not an eligible candidate.",)
        return ()
    if ability == "warp_syphon":
        if is_skip_choice(request, result):
            return ()
        payload = _option_payload(request, result)
        source_model = resolve_model(
            game,
            payload.get("source_model_id") or ctx.get("source_model_id"),
        )
        target_unit = resolve_unit(
            game,
            payload.get("target_unit_id") or ctx.get("target_unit_id"),
        )
        if source_model is None:
            return ("Warp Syphon source model was not found.",)
        if target_unit is None:
            return ("Warp Syphon target unit was not found.",)
        source_unit = getattr(source_model, "parent_unit", None)
        source_army = source_unit.get_parent_army() if hasattr(source_unit, "get_parent_army") else None
        target_root = target_unit.get_attached_unit_root() if hasattr(target_unit, "get_attached_unit_root") else target_unit
        target_army = target_root.get_parent_army() if hasattr(target_root, "get_parent_army") else None
        if source_army is None or target_army is None or source_army is not target_army:
            return ("Warp Syphon target must be friendly.",)
        ts_mgr = getattr(source_army, "thousand_sons_detachments", None)
        can_target_fn = getattr(ts_mgr, "warpforged_warp_syphon_can_target", None) if ts_mgr is not None else None
        if not callable(can_target_fn) or not bool(can_target_fn(source_model, target_root)):
            return ("Warp Syphon target is not eligible.",)
        return ()
    if ability == "command_phase_miracle_discard_return_mode":
        payload = _option_payload(request, result)
        allow_skip = bool(ctx.get("allow_skip", True))
        if is_skip_choice(request, result):
            if not allow_skip:
                return ("Command phase model return choice cannot be skipped.",)
            return ()
        action = str(payload.get("action", "") or "").strip().lower()
        if action == "skip":
            if not allow_skip:
                return ("Command phase model return choice cannot be skipped.",)
            return ()
        if action not in {"base", "discard"}:
            return ("Command phase model return choice is invalid.",)
        source_unit = resolve_unit(
            game,
            payload.get("source_unit_id") or ctx.get("source_unit_id"),
        )
